/* From Uiverse.io by 3bdel3ziz-T  - Tags: simple, minimalist, input, dark, light, radio, custom, css */
.__UIV_SCOPE__ .select {
  width: fit-content;
  cursor: pointer;
  position: relative;
  transition: 300ms;
  color: white;
  overflow: hidden;
}

.__UIV_SCOPE__ .selected {
  background-color: #2a2f3b;
  padding: 5px;
  margin-bottom: 3px;
  border-radius: 5px;
  position: relative;
  z-index: 100000;
  font-size: 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.__UIV_SCOPE__ .arrow {
  position: relative;
  right: 0px;
  height: 10px;
  transform: rotate(-90deg);
  width: 25px;
  fill: white;
  z-index: 100000;
  transition: 300ms;
}

.__UIV_SCOPE__ .options {
  display: flex;
  flex-direction: column;
  border-radius: 5px;
  padding: 5px;
  background-color: #2a2f3b;
  position: relative;
  top: -100px;
  opacity: 0;
  transition: 300ms;
}

.__UIV_SCOPE__ .select:hover > .options {
  opacity: 1;
  top: 0;
}

.__UIV_SCOPE__ .select:hover > .selected .arrow {
  transform: rotate(0deg);
}

.__UIV_SCOPE__ .option {
  border-radius: 5px;
  padding: 5px;
  transition: 300ms;
  background-color: #2a2f3b;
  width: 150px;
  font-size: 15px;
}
.__UIV_SCOPE__ .option:hover {
  background-color: #323741;
}

.__UIV_SCOPE__ .options input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .options label {
  display: inline-block;
}
.__UIV_SCOPE__ .options label::before {
  content: attr(data-txt);
}

.__UIV_SCOPE__ .options input[type="radio"]:checked + label {
  display: none;
}

.__UIV_SCOPE__ .options input[type="radio"]#all:checked + label {
  display: none;
}

.__UIV_SCOPE__ .select:has(.options input[type="radio"]#all:checked) .selected::before {
  content: attr(data-default);
}
.__UIV_SCOPE__ .select:has(.options input[type="radio"]#option-1:checked) .selected::before {
  content: attr(data-one);
}
.__UIV_SCOPE__ .select:has(.options input[type="radio"]#option-2:checked) .selected::before {
  content: attr(data-two);
}
.__UIV_SCOPE__ .select:has(.options input[type="radio"]#option-3:checked) .selected::before {
  content: attr(data-three);
}
